params.command:
$ErrorActionPreference='Stop'
$repo='C:\Users\Xxkan\local-ai-workspaces\mhw-mods'
$wt='C:\Users\Xxkan\agent-worktrees\verify-smb-hardening-551e'
$expected='551e2549d23ddec5471e82d6c510d8f52fc15cd3'
git -C $repo fetch origin --prune
$actual=(git -C $repo rev-parse origin/fix/issue-118-smb-hardening-20260929).Trim()
if($actual -ne $expected){throw "head moved expected=$expected actual=$actual"}
if(Test-Path $wt){git -C $repo worktree remove --force $wt 2>$null; Remove-Item -Recurse -Force $wt -ErrorAction SilentlyContinue}
git -C $repo worktree add --detach $wt $expected
try{
 python -m py_compile "$wt\heaven-bridge\worker.py"
 if($LASTEXITCODE -ne 0){throw 'py_compile failed'}
 python "$wt\heaven-bridge\test_worker.py"
 if($LASTEXITCODE -ne 0){throw 'test_worker.py failed'}
 python -m unittest discover -s "$wt\heaven-bridge\tests" -p "test*.py"
 if($LASTEXITCODE -ne 0){throw 'compat tests failed'}
 git -C $wt diff --check "$((git -C $wt merge-base origin/main HEAD).Trim())..HEAD"
 if($LASTEXITCODE -ne 0){throw 'diff-check failed'}
 Write-Host "VERIFIED_SHA=$expected"
 Write-Host "BRIDGE_TESTS=PASS"
} finally {
 git -C $repo worktree remove --force $wt 2>$null
}
